#!/usr/bin/env python3
"""Verify the self-signed development server certificate."""

import os
import ssl
import sys
from datetime import datetime, timezone

CERT_PATH = "/app/ssl/server.crt"


def main():
    if not os.path.isfile(CERT_PATH):
        print(f"Error: certificate not found at {CERT_PATH}")
        return 1

    try:
        # Loading via the stdlib also validates the PEM structure.
        ssl.PEM_cert_to_DER_cert(open(CERT_PATH).read())
        decoded = ssl._ssl._test_decode_cert(CERT_PATH)
    except Exception as exc:
        print(f"Error: unable to load certificate: {exc}")
        return 1

    common_name = None
    for rdn in decoded.get("subject", ()):
        for key, value in rdn:
            if key == "commonName":
                common_name = value

    not_after = datetime.strptime(
        decoded["notAfter"], "%b %d %H:%M:%S %Y %Z"
    ).replace(tzinfo=timezone.utc)

    print(f"Common Name: {common_name}")
    print(f"Expiration Date: {not_after.strftime('%Y-%m-%d')}")

    if not common_name:
        print("Error: certificate has no Common Name")
        return 1

    if not_after <= datetime.now(timezone.utc):
        print("Error: certificate has expired")
        return 1

    print("Certificate verification successful")
    return 0


if __name__ == "__main__":
    sys.exit(main())
